import { isiOS } from "@utils/index";

// V5 智能选购主容器，负责管理步骤流转和上下文数据
class V5HelpYouChoose extends HTMLElement {
  constructor() {
    super();
    // 当前所在步骤索引，对应 this.steps 中的顺序
    this.currentStepIndex = 0;
    // 步骤顺序配置：使用场景 → 用电设备 → 问题（预算）→ 结果
    this.steps = ["usage", "power", "question", "result"];
    // this.steps = ["result", "question", "power", "usage"];
    // 从 JSON 脚本标签中解析出的多语言文案数据
    this.jsonData = {};
  }

  // 组件插入页面时，初始化多语言数据并渲染首屏步骤
  connectedCallback() {
    // 跨步骤共享的上下文数据，例如 usage/power/question 选择结果
    this.context = {
      compareId: this.getAttribute("compare-id"),
      openAutoDiscountPrice: this.getAttribute("open-auto-discount-price") === "true",
      couponId: this.getAttribute("coupon-id"),
    };
    this.loadJsonData();
    this.renderCurrentStep();
    this.addEventListener("help-step-complete", this.onStepComplete);
    this.addEventListener("help-step-back", this.onStepBack);
    // 滚动仅在前进/后退时触发，移除稳定事件触发的滚动
    this.addEventListener("help-skip-stable-scroll", this._onSkipStableScroll);
    this.initIOSKeyboardFix();
  }
  disconnectedCallback() {
    this.removeEventListener("help-step-complete", this.onStepComplete);
    this.removeEventListener("help-step-back", this.onStepBack);
    // 无稳定事件滚动监听
    this.removeEventListener("help-skip-stable-scroll", this._onSkipStableScroll);
    if (this._vp && this._vpResizeHandler) {
      this._vp.removeEventListener('resize', this._vpResizeHandler);
      this._vpResizeHandler = null;
      this._vp = null;
    }
  }

  // iOS 键盘兼容性处理：防止软键盘收起后页面布局错乱
  initIOSKeyboardFix() {
    if (isiOS() && window.visualViewport) {
      this._vp = window.visualViewport;
      let lastHeight = this._vp.height;
      this.savedScrollY = -1;
      this._vpResizeHandler = () => {
        const keyboardHeight = window.innerHeight - this._vp.height;
        if (keyboardHeight < 100 && this._vp.height > lastHeight) {
          requestAnimationFrame(() => {
            setTimeout(() => {
              if (this.savedScrollY >= 0 && Math.abs(window.scrollY - this.savedScrollY) > 2) {
                window.scrollTo({ top: this.savedScrollY, behavior: 'instant' });
                this.savedScrollY = -1;
              }
            }, 80);
          });
        } else if (keyboardHeight > 100) {
          if (this.savedScrollY < 0) {
            this.savedScrollY = window.scrollY;
          }
        }
        lastHeight = this._vp.height;
      };
      this._vp.addEventListener('resize', this._vpResizeHandler);
    }
  }

  // 子步骤完成时触发，更新上下文并推进到下一步
  onStepComplete = (e) => {
    const { step, value } = e.detail;

    // 更新当前步骤在上下文中的选中值
    this.context[step] = value;
    this.currentStepIndex++;

    this.renderCurrentStep();
    this.scrollToSectionTopStable();

    this.dispatchEvent(new CustomEvent("help-context-update", {
      detail: { context: this.context }
    }));

    // 当到达最后一个步骤时，对外抛出向导完成事件
    if (this.currentStepIndex >= this.steps.length - 1) {
      this.dispatchEvent(new CustomEvent("help-guide-finish", {
        detail: { context: this.context }
      }));
    }
  };

  // 子步骤请求返回上一步时触发，只回退步骤索引，不清空已选上下文
  onStepBack = () => {
    if (this.currentStepIndex > 0) {
      // 清空当前步骤的选择信息
      const currentStep = this.steps[this.currentStepIndex];
      if (currentStep === "usage") {
        delete this.context.usage;
      } else if (currentStep === "power") {
        delete this.context.power;
      } else if (currentStep === "question") {
        delete this.context.question;
      }
      this.currentStepIndex--;
      this.renderCurrentStep();
      this.scrollToSectionTopStable();
    }
  };

  // 根据当前步骤索引，渲染对应的自定义元素并传入多语言和上下文
  async renderCurrentStep() {
    const token = Date.now()
    this._renderToken = token
    const step = this.steps[this.currentStepIndex];
    const tagName = await this.ensureStepDefined(step);
    if (this._renderToken !== token) return
    
    // 如果是结果页，强制移除缓存，确保每次重新渲染
    if (tagName === 'help-you-choose-step-result') {
      const existingResult = this.querySelector(tagName);
      if (existingResult) {
        existingResult.remove();
      }
    }

    // 隐藏所有子组件
    Array.from(this.children).forEach(child => {
      if (child.tagName.toLowerCase().startsWith('help-you-choose-step-')) {
        child.style.display = 'none';
      }
    });

    let currentStepElement = this.querySelector(tagName);
    if (!currentStepElement) {
      currentStepElement = document.createElement(tagName);
      this.appendChild(currentStepElement);
    }
    currentStepElement.style.display = 'block';

    if (currentStepElement && typeof currentStepElement.init === "function") {
      currentStepElement.init(this.jsonData || {}, this.context || {});
    }
    this._prefetchNext();
  }

  async ensureStepDefined(step) {
    const tagName = `help-you-choose-step-${step}`;
    if (!customElements.get(tagName)) {
      let mod;
      if (step === "usage") {
        mod = await import("./steps/usage");
      } else if (step === "power") {
        mod = await import("./steps/power");
      } else if (step === "question") {
        mod = await import("./steps/question");
      } else if (step === "result") {
        mod = await import("./steps/result");
      }
      // 二次检查：避免并发情况下重复 define 抛出 NotSupportedError
      if (mod && mod.default && !customElements.get(tagName)) {
        customElements.define(tagName, mod.default);
      }
    }
    return tagName;
  }

  _prefetchNext() {
    const nextStep = this.steps[this.currentStepIndex + 1]
    if (!nextStep) return
    const fn = async () => {
      const tagName = `help-you-choose-step-${nextStep}`
      if (!customElements.get(tagName)) {
        await this.ensureStepDefined(nextStep)
      }
    }
    if (typeof window.requestIdleCallback === 'function') {
      window.requestIdleCallback(fn, { timeout: 1000 })
    } else {
      setTimeout(fn, 0)
    }
  }

  scrollToSectionTop() {
    if (typeof window === "undefined") return;
    const target = this.closest(".section-padding") || this;
    const rect = target.getBoundingClientRect();
    const top = rect.top + window.pageYOffset;
    window.scrollTo({ top, behavior: "smooth" });
  }
  // 更稳健的滚动：考虑异步渲染与粘性头部，支持二次校准
  scrollToSectionTopStable() {
    // 方案：两帧后测量 + 延迟 160ms 再校准；若用户主动滚动则取消后续校准
    if (typeof window === "undefined") return;
    if (this._skipStableScrollUntil && Date.now() < this._skipStableScrollUntil) return;
    const target = this.closest(".section-padding") || this;
    const headerOffset = this._getHeaderOffset();
    const measure = () => {
      const rect = target.getBoundingClientRect();
      return rect.top + window.pageYOffset - headerOffset;
    };
    const initialY = window.scrollY;
    let canceled = false;
    const cancelIfUserScrolls = () => {
      if (Math.abs(window.scrollY - initialY) > 2) canceled = true;
    };
    // 首次安排
    requestAnimationFrame(() => {
      requestAnimationFrame(() => {
        if (canceled) return;
        const top = measure();
        window.scrollTo({ top, behavior: "smooth" });
        // 延迟校准（覆盖图片/字体加载）
        setTimeout(() => {
          cancelIfUserScrolls();
          if (canceled) return;
          const top2 = measure();
          if (Math.abs(top2 - window.scrollY) > 4) {
            window.scrollTo({ top: top2, behavior: "smooth" });
          }
        }, 160);
      });
    });
  }
  _onSkipStableScroll = (e) => {
    const dur = (e && e.detail && e.detail.duration) || 600;
    this._skipStableScrollUntil = Date.now() + dur;
  }
  _getHeaderOffset() {
    // 估算固定头部高度，避免滚动后标题被遮挡
    const header =
      document.querySelector("sticky-header") ||
      document.querySelector(".shopify-section-header") ||
      document.querySelector("header");
    const rect = header?.getBoundingClientRect?.();
    const isFixed =
      header && window.getComputedStyle(header).position === "fixed";
    return rect && isFixed ? rect.height : 0;
  }
  // 加载 JSON 多语言数据，来源于 theme/snippet 中注入的脚本标签
  loadJsonData() {
    const scriptTag = document.querySelector('script[type="application/json"][id="smart-recommend-5-json"]');
    if (scriptTag) {
      // 提取 JSON 数据并解析
      this.jsonData = JSON.parse(scriptTag.textContent)
    } else {
      this.jsonData = {}
    }
  }
}

customElements.define("v5-help-you-choose", V5HelpYouChoose);
